-- ================================================================
-- Snowflake views generated by qv2dbt from Executive Dashboard.qvs
-- Run top-to-bottom (already in dependency order).
-- ================================================================
create schema if not exists LUNDBECK_UKIE.STAGING;
create schema if not exists LUNDBECK_UKIE.MARTS;

-- AccountGroupMaster  [staging]  (from QlikView 'qvd')
create or replace view LUNDBECK_UKIE.STAGING.STG_ACCOUNT_GROUP_MASTER as
select
    AccountGroup,
    AccountGroupDesc
from LUNDBECK_UKIE.RAW.ACCOUNTGROUPMASTER as base
;

-- AccountMaster  [staging]  (from QlikView 'qvd')
create or replace view LUNDBECK_UKIE.STAGING.STG_ACCOUNT_MASTER as
select
    Account,
    AccountGroup
from LUNDBECK_UKIE.RAW.ACCOUNTMASTER as base
;

-- Accounts  [staging]  (from QlikView 'qvd')
create or replace view LUNDBECK_UKIE.STAGING.STG_ACCOUNTS as
select
    Account,
    AccountDesc
from LUNDBECK_UKIE.RAW.ACCOUNTS as base
;

